#include <avr/io.h>
#include <avr/interrupt.h>
#include <avr/sleep.h>
#include <stdint.h>

#define F_CPU 16000000UL

/* Timer 0 in CTC mode ticks every millisecond: F_CPU/64 counts,
 * OCR0A picked so one compare = 1 ms exactly at this clock. The same
 * one-tick contract the 8051 build keeps — nothing generated here
 * ever busy-waits on a cycle count. */
#define BW_OCR0A ((uint8_t)(F_CPU / 64UL / 1000UL - 1UL))

/* One script = one cooperative task. Timer interrupts every millisecond;
 * tasks yield at every wait and at every loop iteration (Scratch's own
 * scheduling contract), so no task can starve the others. */
static volatile uint32_t bw_ms;
static uint8_t bw_calm;

ISR(TIMER0_COMPA_vect)
{
    bw_ms++;
}

/* A 32-bit read is not atomic on an 8-bit AVR; hold interrupts off. */
static uint32_t bw_now(void)
{
    uint32_t t;
    cli();
    t = bw_ms;
    sei();
    return t;
}

/* 10-bit ADC, polled, AVcc reference. Channel = the A-pin number;
 * A6/A7 exist on the Nano as ADC-only pads and work here too. */
static long adc_read(unsigned char channel)
{
    ADMUX = (uint8_t)((1 << REFS0) | (channel & 0x0F));
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC)) ;
    return ADC;
}

/* PWM on the OC pins of Timers 1 and 2 (D9/D10, D11/D3) — 8-bit
 * fast PWM at F_CPU/64/256 ≈ 977 Hz, the analogWrite frequency.
 * Timer 0 is the millisecond tick, so D5/D6 are refused at emit
 * time. 0%% and 100%% disconnect the compare unit and drive the
 * level directly — fast PWM cannot express either exactly. */
static void pwm_set(unsigned char pin, unsigned int percent)
{
    uint8_t v;
    if (percent > 100) percent = 100;
    v = (uint8_t)((percent * 255u + 50u) / 100u);
    switch (pin) {
    case 3:   /* OC2B */
        DDRD |= (1 << 3);
        if (v == 0)        { TCCR2A &= (uint8_t)~(1 << COM2B1); PORTD &= (uint8_t)~(1 << 3); }
        else if (v == 255) { TCCR2A &= (uint8_t)~(1 << COM2B1); PORTD |= (1 << 3); }
        else               { TCCR2A |= (1 << COM2B1); OCR2B = v; }
        break;
    case 9:   /* OC1A */
        DDRB |= (1 << 1);
        if (v == 0)        { TCCR1A &= (uint8_t)~(1 << COM1A1); PORTB &= (uint8_t)~(1 << 1); }
        else if (v == 255) { TCCR1A &= (uint8_t)~(1 << COM1A1); PORTB |= (1 << 1); }
        else               { TCCR1A |= (1 << COM1A1); OCR1A = v; }
        break;
    case 10:  /* OC1B */
        DDRB |= (1 << 2);
        if (v == 0)        { TCCR1A &= (uint8_t)~(1 << COM1B1); PORTB &= (uint8_t)~(1 << 2); }
        else if (v == 255) { TCCR1A &= (uint8_t)~(1 << COM1B1); PORTB |= (1 << 2); }
        else               { TCCR1A |= (1 << COM1B1); OCR1B = v; }
        break;
    case 11:  /* OC2A */
        DDRB |= (1 << 3);
        if (v == 0)        { TCCR2A &= (uint8_t)~(1 << COM2A1); PORTB &= (uint8_t)~(1 << 3); }
        else if (v == 255) { TCCR2A &= (uint8_t)~(1 << COM2A1); PORTB |= (1 << 3); }
        else               { TCCR2A |= (1 << COM2A1); OCR2A = v; }
        break;
    default: break;
    }
}

/* Variables: long, matching Scratch's number range — int is 16-bit on
 * sdcc/avr-gcc/cc65 and silently wraps mid-expression (76-multimeter). */
static long s0_sensorMin = 0;   /* Cat: sensorMin */
static long s0_sensorMax = 0;   /* Cat: sensorMax */
static long s0_sensorValue = 0;   /* Cat: sensorValue */
static long s0_sample1 = 0;   /* Cat: sample1 */
static long s0_sample2 = 0;   /* Cat: sample2 */
static long s0_sample3 = 0;   /* Cat: sample3 */
static long s0_sample4 = 0;   /* Cat: sample4 */
static long s0_outputValue = 0;   /* Cat: outputValue */

/* REPEAT counters live across yields. */
static long bw_i1;

static volatile unsigned int bw_task0_state;
static volatile unsigned int bw_task0_until;
// Ported from arduino-examples/examples/03.Analog/Calibration/Calibration.ino, CC0
/* when green flag clicked (script 1, Cat) */
static void bw_task0(void)
{
    switch (bw_task0_state) {
    case 0:
    s0_sensorMin = 1023;
    s0_sensorMax = 0;
    PORTB |= (1 << 5);
    /* Calibrate for 5 seconds */
    bw_i1 = (100);
    bw_task0_state = 1;
    case 1:
    if (bw_i1 > 0) {
        s0_sensorValue = adc_read(0);
        if ((s0_sensorValue > s0_sensorMax)) {
            s0_sensorMax = s0_sensorValue;
        }
        if ((s0_sensorValue < s0_sensorMin)) {
            s0_sensorMin = s0_sensorValue;
        }
        bw_task0_until = bw_now() + (50);
        bw_task0_state = 2;
        case 2:
        if ((int)(bw_now() - bw_task0_until) < 0) return;
        bw_i1--;
        bw_task0_state = 1;
        return;
    }
    PORTB &= (uint8_t)~(1 << 5);
    /* The filter, sized so its cost can be STATED rather than guessed. */
    /* Four samples, written as an explicit shift register rather than with a */
    /* list: the device C emitter has no lists, so the list form used in */
    /* arduino-03-smoothing lowers to comments and a constant 0 — a filter that */
    /* is present in the simulator and absent on the chip. This one lowers to */
    /* four `long` assignments and behaves the same in both. */
    /* The loop below runs every 20 ms, so this window takes */
    /* 4 x 20 ms = 80 ms to follow a step all the way, and lags a steady ramp */
    /* by (4 - 1) / 2 x 20 ms = 30 ms. Shorten the window and the light is */
    /* twitchier and sooner; lengthen it and it is calmer and later. */
    s0_sample1 = 0;
    s0_sample2 = 0;
    s0_sample3 = 0;
    s0_sample4 = 0;
    /* Main loop: average the raw reading, then map the calibrated range to the LED */
    bw_task0_state = 3;
    case 3:
    s0_sample4 = s0_sample3;
    s0_sample3 = s0_sample2;
    s0_sample2 = s0_sample1;
    s0_sample1 = adc_read(0);
    s0_sensorValue = (((s0_sample1 + s0_sample2) + (s0_sample3 + s0_sample4)) / 4);
    if ((s0_sensorValue < s0_sensorMin)) {
        s0_sensorValue = s0_sensorMin;
    }
    if ((s0_sensorValue > s0_sensorMax)) {
        s0_sensorValue = s0_sensorMax;
    }
    s0_outputValue = (((s0_sensorValue - s0_sensorMin) * 100) / (s0_sensorMax - s0_sensorMin));
    pwm_set(9, s0_outputValue);
    bw_task0_until = bw_now() + (20);
    bw_task0_state = 4;
    case 4:
    if ((int)(bw_now() - bw_task0_until) < 0) return;
    bw_task0_state = 3;
    return;
    }
    bw_task0_state = 0xFFFF;   /* ran to the end */
}

/* Register setup: ports, ADC, Timer 0. Kept out of main() so the program
 * body stands alone — a C -> blocks reader can then tell them apart. */
static void bw_setup(void)
{
    DIDR0 |= (1 << 0);     /* sensor: digital buffer off on ADC0 */
    PORTB &= (uint8_t)~(1 << 5);      /* statusLed: start OFF */
    DDRB |= (1 << 5);     /* statusLed = D13 output */
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);  /* on, /128 */
    TCCR0A = (1 << WGM01);         /* Timer 0 CTC */
    TCCR0B = (1 << CS01) | (1 << CS00);  /* F_CPU/64 */
    OCR0A  = BW_OCR0A;             /* one compare = 1 ms */
    TIMSK0 = (1 << OCIE0A);        /* millisecond tick */
    TCCR1A = (1 << WGM10);         /* Timer 1: 8-bit fast PWM */
    TCCR1B = (1 << WGM12) | (1 << CS11) | (1 << CS10);  /* F_CPU/64 */
    TCCR2A = (1 << WGM20) | (1 << WGM21);  /* Timer 2: fast PWM */
    TCCR2B = (1 << CS22);          /* F_CPU/64 */
}

int main(void)
{
    bw_setup();
    set_sleep_mode(SLEEP_MODE_IDLE);  /* timers keep running; the tick wakes us */
    sleep_enable();
    sei();                         /* tick on */

    for (;;) {
        uint32_t pass_ms = bw_now();
        bw_task0();
        /* Two full passes inside one millisecond: sleep to the next
         * tick instead of spinning the core against it — the same
         * contract the pico target keeps (its DONE row has the 110x
         * measurement), spelled in avr-libc. The emulator adapter
         * fast-forwards the SLEEP opcode; silicon idles. */
        if (bw_now() == pass_ms) { if (++bw_calm >= 2u) { bw_calm = 0u; sleep_cpu(); } }
        else bw_calm = 0u;
    }
}
